bank = [r for r in rows if r["source"] == "bank"]
ledger = [r for r in rows if r["source"] == "ledger"]
pairs, used = [], set()
for b in sorted(bank, key=lambda r: r["id"]):
    for l in sorted(ledger, key=lambda r: r["id"]):
        if l["id"] not in used and l["ref"] == b["ref"] and b["ref"] and abs(l["amount"] - b["amount"]) < 0.005:
            pairs.append([b["id"], l["id"]]); used.add(l["id"]); used.add(b["id"]); break
differences = []
left_bank = [b for b in bank if b["id"] not in used]
left_ledger = [l for l in ledger if l["id"] not in used]
for b in list(left_bank):
    same = [l for l in left_ledger if l["ref"] == b["ref"] and b["ref"]]
    if same:
        l = same[0]
        differences.append({"kind": "fee", "bank": b["id"], "ledger": l["id"], "amount": round(b["amount"] - l["amount"], 2)})
        left_bank.remove(b); left_ledger.remove(l)
paired_refs = {l["ref"] for l in ledger if l["id"] in used}
for l in left_ledger:
    kind = "duplicate" if l["ref"] in paired_refs else ("timing" if l["date"] >= "2026-10-28" else "unknown")
    differences.append({"kind": kind, "bank": None, "ledger": l["id"], "amount": round(-l["amount"], 2)})
for b in left_bank:
    kind = "fee" if "fee" in b["text"] else "unknown"
    differences.append({"kind": kind, "bank": b["id"], "ledger": None, "amount": round(b["amount"], 2)})
result = {"pairs": pairs, "differences": differences, "total": round(sum(d["amount"] for d in differences), 2)}
